  awk '"'BEGIN{FS=OFS=\"\\t\"} NR==FNR{keep["'$1]=1; next} FNR==1 || keep[$1]'"' run_trace/retained_gene_ids.txt \""'$src" > "run_trace/filtered_counts/${base}.filtered.tabular"
done
{
  printf '"'%s\\t%s\\n' \"timestamp_utc\" \""'$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  printf '"'%s\\t%s\\n' \"assigned_history_id\" \"bbd44e69cb8906b54b24bbddc267e704\"
