  printf '%s\\t%s\\n' \"retained_genes\" \""'$(wc -l < run_trace/retained_gene_ids.txt)"
} > run_trace/execution_log.tsv
wc -l run_trace/retained_gene_ids.txt run_trace/filtered_counts/*.filtered.tabular
